import { mix, spring, stagger, wrap } from "motion";

const delay = stagger(0.125, { startDelay: 0.25 });
let position = 0;
let phase = 0;
let schedule = 0;
let springDigest = 0;

for (let index = 0; index < 160_000; index += 1) {
  const lane = index % 8;
  position += mix(-120, 360, lane / 8);
  phase += wrap(0, 360, index * 47);
  schedule += delay(lane, 8) * 8;
}

const generator = spring({
  keyframes: [0, 100],
  stiffness: 170,
  damping: 26,
  mass: 1,
});
for (let time = 0; time <= 1_024; time += 16) {
  springDigest += Math.round(generator.next(time).value * 1_000);
}

console.log(`motion-vite:${position}:${phase}:${schedule}:${springDigest}`);

function mixValue(from, to, progress) {
  return from + (to - from) * progress;
}

function wrapValue(min, max, value) {
  const range = max - min;
  return ((((value - min) % range) + range) % range) + min;
}

function staggerDelay(step, start, index) {
  return start + step * index;
}

function createSpring(stiffness, damping, mass, origin, target) {
  const state = { done: false, value: origin };
  const initialVelocity = 0;
  const dampingRatio = damping / (2 * Math.sqrt(stiffness * mass));
  const initialDelta = target - origin;
  const undampedAngularFreq = Math.sqrt(stiffness / mass) / 1000;
  const angularFreq =
    undampedAngularFreq * Math.sqrt(1 - dampingRatio * dampingRatio);
  const amplitude =
    (initialVelocity + dampingRatio * undampedAngularFreq * initialDelta) /
    angularFreq;
  const sinCoeff =
    dampingRatio * undampedAngularFreq * amplitude +
    initialDelta * angularFreq;
  const cosCoeff =
    dampingRatio * undampedAngularFreq * initialDelta -
    amplitude * angularFreq;

  return (time) => {
    const envelope = Math.exp(-dampingRatio * undampedAngularFreq * time);
    const sin = Math.sin(angularFreq * time);
    const cos = Math.cos(angularFreq * time);
    const current =
      target - envelope * (amplitude * sin + initialDelta * cos);
    const currentVelocity =
      1000 * envelope * (sinCoeff * sin + cosCoeff * cos);
    state.done =
      Math.abs(currentVelocity) <= 2 && Math.abs(target - current) <= 0.5;
    state.value = state.done ? target : current;
    return state;
  };
}

let position = 0;
let phase = 0;
let schedule = 0;
let springDigest = 0;
for (let index = 0; index < 160_000; index += 1) {
  const lane = index % 8;
  position += mixValue(-120, 360, lane / 8);
  phase += wrapValue(0, 360, index * 47);
  schedule += staggerDelay(0.125, 0.25, lane) * 8;
}

const spring = createSpring(170, 26, 1, 0, 100);
for (let time = 0; time <= 1024; time += 16) {
  springDigest += Math.round(spring(time).value * 1000);
}

console.log(`motion:${position}:${phase}:${schedule}:${springDigest}`);

pure float mixValue(float from, float to, float progress) {
  return from + (to - from) * progress;
}

pure int wrapValue(int min, int max, int value) {
  int range = max - min;
  return ((value - min) % range + range) % range + min;
}

pure float staggerDelay(float step, float start, int index) {
  return start + step * index;
}

class SpringState {
  bool done;
  float value;

  init(float origin) {
    this.done = false;
    this.value = origin;
  }
}

void springNext(
  SpringState state,
  float time,
  float target,
  float dampingRatio,
  float undampedAngularFreq,
  float angularFreq,
  float amplitude,
  float initialDelta,
  float sinCoeff,
  float cosCoeff
) {
  float envelope = (-dampingRatio * undampedAngularFreq * time).exp();
  float sin = (angularFreq * time).sin();
  float cos = (angularFreq * time).cos();
  float current = target - envelope * (amplitude * sin + initialDelta * cos);
  float currentVelocity = 1000.0 * envelope * (sinCoeff * sin + cosCoeff * cos);
  state.done = currentVelocity.abs() <= 2.0 && (target - current).abs() <= 0.5;
  if (state.done) {
    state.value = target;
  } else {
    state.value = current;
  }
}

float position = 0.0;
int phase = 0;
float schedule = 0.0;
float springDigest = 0.0;
for (int index = 0; index < 160000; index++) {
  int lane = index % 8;
  position += mixValue(-120.0, 360.0, lane / 8.0);
  phase += wrapValue(0, 360, index * 47);
  schedule += staggerDelay(0.125, 0.25, lane) * 8.0;
}

float stiffness = 170.0;
float damping = 26.0;
float mass = 1.0;
float origin = 0.0;
float target = 100.0;
float initialVelocity = 0.0;
float dampingRatio = damping / (2.0 * (stiffness * mass).sqrt());
float initialDelta = target - origin;
float undampedAngularFreq = (stiffness / mass).sqrt() / 1000.0;
float angularFreq = undampedAngularFreq * (1.0 - dampingRatio * dampingRatio).sqrt();
float amplitude =
  (initialVelocity + dampingRatio * undampedAngularFreq * initialDelta) / angularFreq;
float sinCoeff = dampingRatio * undampedAngularFreq * amplitude + initialDelta * angularFreq;
float cosCoeff = dampingRatio * undampedAngularFreq * initialDelta - amplitude * angularFreq;
SpringState spring = new SpringState(origin);
for (int time = 0; time <= 1024; time += 16) {
  springNext(
    spring,
    time,
    target,
