const todos = store.getState().todos.items;
check(todos.length === 1);
check(todos[0].id === 1 && todos[0].text === "x" && todos[0].done === true);
check(increment().type === "counter/increment");
check(addTodo({ id: 0, text: "" }).type === "todos/addTodo");

