function formatResult(result) {
  if (result.success) {
    if (result.data === undefined) return "ok:undefined";
    return `ok:${JSON.stringify(result.data)}`;
  }
  return `err:${result.error.issues
    .map((issue) => `${issue.code}@${issue.path.join("/")}:${issue.message}`)
    .join(";")}`;
}

