async function mount(kind) {
  const dom = new JSDOM(
    '<!doctype html><html><head></head><body><main id="app"></main><aside id="portal-target"></aside><svg id="svg-portal-target"></svg><aside id="shadow-portal-target"></aside></body></html>',
    { url: "http://localhost/", runScripts: "outside-only" },
  );
  if (kind === "solidlil") installDomHost(dom.window);
  dom.window.__lsxRuntimeKind = kind;
  dom.window.registerLsxDispose = (dispose) => {
    dom.window.__disposeLsx = dispose;
  };
  dom.window.registerLsxDiagnostics = (
    ownerSlots,
    effectSlots,
    freeOwnerSlots,
    freeEffectSlots,
    pendingEffects,
  ) => {
    dom.window.__lsxDiagnostics = () => ({
      owners: ownerSlots(),
      effects: effectSlots(),
      freeOwners: freeOwnerSlots(),
      freeEffects: freeEffectSlots(),
      pendingEffects: pendingEffects(),
    });
  };
  installLsxBoundaryDiagnostics(dom.window);
  dom.window.eval(
    kind === "solidlil" ? compileFixture() : await compileSolidFixture(),
  );
  return dom;
}

function mountBuilt(kind) {
  const dom = new JSDOM(
    '<!doctype html><html><head></head><body><main id="app"></main><aside id="portal-target"></aside><svg id="svg-portal-target"></svg><aside id="shadow-portal-target"></aside></body></html>',
    { url: "http://localhost/", runScripts: "outside-only" },
  );
  dom.window.__lsxRuntimeKind = `${kind}-built`;
  installLsxBoundaryDiagnostics(dom.window);
  dom.window.eval(
    readFileSync(
